    const menu=document.createElement('div');menu.id='fileActionsMenu';menu.className='file-actions-menu';menu.setAttribute('role','menu');menu.setAttribute('aria-label','File actions for '+rec.name);
    menu.innerHTML=[['Rename','org-rename','edit'],['Duplicate','org-duplicate','layers'],['Campaign & tags','org-organise','folder'],['Move to Trash','org-trash','trash']].filter(([,action])=>action!=='org-rename'||M.navigation.parse(state.hash).view!=='review').map(([label,action,glyph])=>`<button role="menuitem" tabindex="-1" data-action="${action}" ${rec.unavailable&&['org-save','org-duplicate'].includes(action)?'disabled':''}>${icon(glyph)}<span>${label}</span></button>`).join('');
