  function heading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${h(title)}</h1>${subtitle?`<p>${h(subtitle)}</p>`:''}</div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
  // Shared presentation only: job state, submitted requirements and paid actions stay unchanged.
