    const header=document.createElement('header');header.className='flow-header';
    header.innerHTML=`${draft?'':`<div class="flow-topline"><a class="text-button" href="#${h(back)}">${icon('back')}${h(backLabel)}</a><div class="flow-header-status">${!p.local&&window.CreativeAccount?button('Report an issue','report-issue','text-button','message'):''}${statusBadge(p)}</div></div>`}<div class="flow-title"><div><h1>${h(draft||(view==='review'&&p.local)?title:p.name||'Your project')}</h1>${draft||view==='review'?'':`<div class="flow-context">${flowContext(p)}</div>`}</div></div>${draft?flowSteps(M.confirmationCurrent(p)?2:0):view==='review'?'':`<nav class="flow-nav" aria-label="Project workspace"><a href="#project/${h(p.id)}" ${['project','review','download','versions'].includes(view)?'aria-current="page"':''}>Artwork</a><button type="button" data-flow-brief>${p.local?'Brief':'Submitted brief'}</button></nav>`}`;
