    const assets=p.local?(p.outputs||[]).map(o=>o.name||M.features.find(f=>f.id===o.featureId)?.name):(p.placements||[]).map(v=>v.name);
    const refs=Array.isArray(input.references)?input.references:Array.isArray(p.references)?p.references:[],docs=Array.isArray(input.briefDocuments)?input.briefDocuments:Array.isArray(p.briefDocuments)?p.briefDocuments:[];
    const dialog=assignmentDialog(p.local?'Saved brief':'Submitted brief',`<div class="flow-context">${flowContext(p)}</div><p class="hint">The saved request for this project.</p><section class="brief-review-section"><h3>Your request</h3><p class="brief-prose">${h(p.brief||input.brief||'No brief text was saved for this project.')}</p><dl class="brief-review-facts">${row('Product / SKU',productContext(p))}${row('Main message',input.message||input.objective)}${row('Audience',input.audience)}${row('Language',input.language)}${row('Features',input.rtbs)}${row('Must include',input.mandatoryInfo)}${['objective','market','desiredAction','focusType','creativeType','productVariantId','productPageUrl','placementPublishing','placementViewing','ageGroups','cities','markets','tone','cta','landingPageUrl','selectedVariant','variant','offer','deadline','constraints','visualDirection','selectedRtbs','communicationGoal'].map(key=>row(key.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase()),input[key]||p[key])).join('')}</dl></section><section class="brief-review-section"><h3>Requested deliverables</h3><ul>${assets.filter(Boolean).map(a=>`<li>${h(a)}</li>`).join('')||'<li>No deliverables recorded.</li>'}</ul></section><section class="brief-review-section"><h3>References & documents</h3><ul>${[...refs,...docs].map(r=>`<li>${h(typeof r==='string'?r:r.name||r.label||'Saved reference')}</li>`).join('')||'<li>No attachment names recorded.</li>'}</ul></section>`);
