  function composer(){const id=state.brand.id;if(!composerByBrand[id]){try{if(!homeStorage)throw Error('Device storage is unavailable. Keep this page open or copy your inputs.');composerByBrand[id]=homeStorage.read(id);}catch(e){composerErrors[id]=clientError(e,'save');composerByBrand[id]={version:1,brandId:id,revision:0,data:{prompt:'',productId:'',audience:'',style:'',featureId:1,formatChosen:false}};}}return composerByBrand[id].data;}
