    const artwork=[...allProjects().flatMap(p=>(p.results||[]).filter(r=>!orgMeta(M.creativeKey(p,r)).trashedAt)).filter(r=>r.ready===true&&M.safeAsset(r.imageUrl)),...state.products.map(p=>({imageUrl:productImage(p)})).filter(r=>M.safeAsset(r.imageUrl))].slice(0,3);
