  function showHelp(el){if(!el?.isConnected)return;hideHelp();helpAnchor=el;helpBubble.textContent=el.dataset.helpCopy;el.setAttribute('aria-describedby',helpBubble.id);helpBubble.showPopover();const r=el.getBoundingClientRect(),b=helpBubble.getBoundingClientRect();helpBubble.style.left=Math.max(8,Math.min(r.left-8,innerWidth-b.width-8))+'px';helpBubble.style.top=Math.max(8,r.bottom+8+b.height<=innerHeight-8?r.bottom+8:r.top-b.height-8)+'px';}
