  function syncSidebar(){const mobile=matchMedia('(max-width:700px)').matches,expanded=mobile?document.body.classList.contains('sidebar-mobile-open'):!document.body.classList.contains('sidebar-collapsed');const b=$('#sidebarToggle');b.setAttribute('aria-expanded',String(expanded));b.setAttribute('aria-label',expanded?'Collapse sidebar':'Expand sidebar');b.title=expanded?'Collapse sidebar':'Expand sidebar';}
