    if(tab==='security')body=`<h2>Login & security</h2><p class="settings-description">Your future sign-in and account security controls.</p>${notice('Login is not connected. The studio currently uses shared local access; profiles do not separate or protect user data.')}<div class="settings-row"><div><h3>Sign-in method</h3><p>Email or organisation login</p></div><button class="button secondary" disabled>Connect login</button></div><div class="settings-row"><div><h3>Password & account recovery</h3><p>Managed through your future login provider.</p></div>${unconnected}</div><div class="settings-row"><div><h3>Active sessions</h3><p>No authenticated sessions to display.</p></div><button class="button secondary" disabled>Sign out</button></div>`;
