  function collectionInputs(d){return `<div class="collection-inputs" id="field-productIds"><h3>Products in this collection</h3><p class="hint">Use saved products from ${h(state.brand.name)}. Select each exact variant.</p>${state.products.length?state.products.map(p=>`<div class="collection-product"><label><input type="checkbox" data-collection-product="${h(p.id)}" ${(d.productIds||[]).includes(p.id)?'checked':''}>${h(p.name)}</label>${(d.productIds||[]).includes(p.id)&&p.variants?.length?`<label class="field"><span>Variant for ${h(p.name)}</span><select data-collection-variant="${h(p.id)}"><option value="">Choose variant…</option>${p.variants.map(v=>`<option value="${h(v.id)}" ${String(d.collectionVariants?.[p.id])===String(v.id)?'selected':''}>${h(v.name||v.id)}</option>`).join('')}</select></label>`:''}</div>`).join(''):'<p class="hint">No saved products are available. Open the product library to add them.</p>'}<p class="field-error">${h(state.draftErrors.productIds||'')}</p></div>`;}
