    if(action==='static-part-pdp-restore'&&o.pdpPrevious){Object.assign(o,{staticParts:o.pdpPrevious.parts,width:o.pdpPrevious.width,height:o.pdpPrevious.height,formatId:o.pdpPrevious.formatId,pdpPack:false});delete o.pdpPrevious;dirty();if(saveDraft())renderRoute();return;}
