  function field(name,label,value,options={}){const error=state.draftErrors[name],id='field-'+name;return `<label class="field ${options.full?'full':''}" for="${id}"><span>${name==='brief'?sectionCue('file','blush'):''}${h(label)}${options.required?' <span class="intake-required" aria-label="Required">*</span>':''}${state.draft?.intakeVersion>=2&&name!=='brief'?provenance(name):''}</span>${options.select?`<select id="${id}" data-field="${name}" ${options.required?'required aria-required="true"':''} ${error?'aria-invalid="true"':''}>${options.select.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return `<option value="${h(v)}" ${String(value)===String(v)?'selected':''}>${h(t)}</option>`;}).join('')}</select>`:options.type==='textarea'?`<textarea id="${id}" data-field="${name}" placeholder="${h(options.placeholder||'')}" ${error?'aria-invalid="true"':''} aria-describedby="error-${name}">${h(value)}</textarea>`:`<input id="${id}" data-field="${name}" type="${options.type||'text'}" value="${h(value)}" placeholder="${h(options.placeholder||'')}" ${error?'aria-invalid="true"':''} aria-describedby="error-${name}">`}<small id="error-${name}" class="field-error">${h(error||'')}</small>${options.hint?`<small class="hint">${h(options.hint)}</small>`:''}</label>`;}
