  function assetSummary(o,d=state.draft){const count=M.units({...d,outputs:[o]}),parts=M.staticParts(o),sizes=[...new Set((parts.length?parts:[o]).map(p=>`${p.width} × ${p.height}`))];return `${count} ${count===1?'item':'items'} per set · ${sizes.length===1?sizes[0]+' px':sizes.length+' sizes'} · ${o.language||d.language}`;}
