  async function importBriefDocument(file,identity){const d=identity||state.draft,brandId=d.brandId,id=d.id,k=brandId+':'+id;if(documentImporting.has(k))return;if((state.draft?.briefDocuments||[]).length>=20)throw Error('Use at most 20 documents per brief.');documentImporting.add(k);if($('#briefPdf'))$('#briefPdf').innerHTML=briefPdfView();try{const doc=await StudioDocuments.upload(d,file);changeReferenceDraft(brandId,id,current=>{current.briefDocuments??=[];if(!current.briefDocuments.some(x=>x.id===doc.id))current.briefDocuments.push(doc);M.applyBriefAutofill(current,{products:state.brand.id===brandId?state.products:[]});});if(state.draft?.id===id&&state.draft.brandId===brandId){const active=document.activeElement,focusId=active?.id,start=active?.selectionStart,end=active?.selectionEnd,x=scrollX,y=scrollY;intakeOpen.set(id+':attachments',true);renderRoute();const next=focusId&&document.getElementById(focusId);next?.focus({preventScroll:true});if(typeof start==='number'&&next?.setSelectionRange)next.setSelectionRange(start,end);window.scrollTo(x,y);}toast('Original saved. Review the imported text and filled details.');}catch(e){toast(e.message||'Import failed. Your brief is preserved.');}finally{documentImporting.delete(k);if(state.draft?.id===id&&state.draft.brandId===brandId&&$('#briefPdf'))$('#briefPdf').innerHTML=briefPdfView();}}

  function intakeChips(key,label,options,values=[]){values=Array.isArray(values)?values:[];return `<fieldset class="intake-chips"><legend>${h(label)}</legend>${options.map(value=>`<label><input type="checkbox" data-intake-chip="${key}" value="${h(value)}" ${values.includes(value)?'checked':''}><span>${h(value)}</span></label>`).join('')}</fieldset>`;}
