      let value=group?[...form.querySelectorAll('[data-intake-chip]')].filter(x=>x.dataset.intakeChip===group&&x.checked).map(x=>x.value).join('; '):el.tagName==='SELECT'?el.selectedOptions[0]?.textContent:el.value;
