      rows.push(`<li><div><strong>${h(label?.trim()||'Image setting')}</strong>${placement?`<small>${h(placement)}</small>`:''}<p>${h(value||'Not provided')}</p></div><button type="button" class="text-button" data-intake-jump="${h(el.id)}">${el.readOnly?'View':'Edit'}</button></li>`);
