  document.addEventListener('click',e=>{const b=e.target.closest('[data-intake-jump]');if(!b)return;const el=document.getElementById(b.dataset.intakeJump);if(!el)return;for(let p=el.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;el.scrollIntoView({block:'center'});el.focus({preventScroll:true});});
