  function intakeOptionalGroup(key,title,note,body){return `<section class="intake-optional-group" data-intake-section="${h(key)}"><h3>${h(title)}</h3><div class="hint">${h(note)}</div>${body}</section>`;}
  const audiencePresets={audience:{label:'Audience',options:['Working professionals','Families','New homeowners','Students'],placeholder:'e.g. People replacing their mattress'},customerAge:{label:'Age groups',options:['18–24','25–34','35–44','45–54','55+'],placeholder:'e.g. 30–45',broad:'All adults'},markets:{label:'Cities & markets',options:['Tier 1 / metros','Tier 2','Tier 3 & smaller towns','Pan India'],placeholder:'e.g. Bengaluru or South India',broad:'Pan India'}};
  function audienceChoices(key,d){const config=audiencePresets[key],selected=String(d[key]||'').split(';').map(v=>v.trim()).filter(Boolean),options=[...new Set([...config.options,...selected])];return `<fieldset class="audience-choices" data-audience-group="${key}"><legend><span class="audience-legend">${sectionCue(key==='customerAge'?'age':key==='markets'?'globe':'users','blue')}<span>${h(config.label)}</span></span></legend><input type="hidden" id="field-${key}" data-field="${key}" value="${h(d[key]||'')}"><div class="audience-chip-row">${options.map(v=>`<button type="button" class="audience-chip" data-audience-choice="${key}" data-value="${h(v)}" aria-pressed="${selected.includes(v)}">${selected.includes(v)?'<span aria-hidden="true">✓</span> ':''}${h(v==='Tier 3 & smaller towns'?'Tier 3':v)}</button>`).join('')}<button type="button" class="text-button intake-add audience-add" data-audience-expand="${key}" aria-expanded="false" aria-controls="audience-custom-${key}">Add</button></div><div class="audience-custom" id="audience-custom-${key}" hidden><input aria-label="Custom ${h(config.label.toLowerCase())}" data-audience-custom="${key}" maxlength="500" placeholder="${h(config.placeholder)}"><button type="button" class="text-button intake-add" data-audience-save="${key}">Add</button></div></fieldset>`;}
