  function progressView(p){if(p.componentRecovery?.units?.length&&!state.demo)return breadcrumbs([['Projects','#projects'],[p.name,'#project/'+p.id],['Progress']])+heading('Design progress',p.name)+projectRecovery(p)+`<a class="button primary" href="#project/${h(p.id)}">View available designs</a><p id="progressConnection" role="status"></p>`;const progress=M.jobProgress(p);if(!state.demo&&progress.current==='ready'&&state.confirmedProgress?.get(p.id)!==p.status)return breadcrumbs([['Projects','#projects'],[p.name,'#project/'+p.id],['Progress']])+heading('Checking the latest status',p.name)+`<section class="surface progress-main"><p id="progressConnection" role="status" aria-live="polite">Checking the latest status…</p><div id="progressError"></div></section>`;const needs=p.status==='needs-input',failed=['failed','partial'].includes(p.status);return breadcrumbs([['Projects','#projects'],[p.name,'#project/'+p.id],['Progress']])+heading(M.status(p).label,p.name)+journeySteps('progress',p)+`<div class="progress-layout"><section class="surface progress-main"><ol class="recorded-progress" aria-label="Creation stages">${progress.steps.map(s=>`<li class="${s.state}" ${s.state==='current'?'aria-current="step"':''}><span aria-hidden="true">${s.state==='completed'?'✓':s.state==='current'?'●':'○'}</span>${s.label}</li>`).join('')}</ol><span class="progress-orbit ${progress.running?'running':''}">${icon(progress.running?'spark':failed?'info':'check')}</span><h2>${h(progress.label)}</h2>${progress.substage?`<p class="progress-substage">${h(progress.substage)}</p>`:''}<p class="hint">${h(progress.description)}</p><p class="hint" id="progressConnection" role="status" aria-live="polite"></p><div id="progressError"></div><p class="hint">${(p.results||[]).filter(r=>r.imageUrl).length} images saved so far. ${p.updatedAt?'Last recorded update: '+h(new Date(p.updatedAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})):''}</p><p class="hint">You can leave this page and return. Refreshing status does not start another paid request. <a href="#costs">View usage &amp; costs</a></p><div class="actions">${state.demo?button('View example outputs','check-progress','primary','arrow'):''}<a class="button primary" href="#project/${h(p.id)}">${progress.running?'View available work':'View designs'}</a>${failed&&!state.demo?button('Review recovery options','restart-project','secondary',''):''}${needs||failed?`<a class="text-button" href="#settings/diagnostics">Get help ${icon('arrow')}</a>`:''}</div><div id="restartPanel" aria-live="polite"></div>${failed?stateCard('Creation did not finish',clientError(p.error,'generation'),'','error'):''}</section></div>`;}

  function scorecard(data){return `<section class="design-scorecard"><div class="scorecard-heading"><h3>Creative Scorecard</h3><span>Saved review · not performance</span></div>${data.scores.map(q=>`<div class="score-row"><strong>${h(q.title)}</strong><div class="score-meter" role="img" aria-label="${q.score===null?'Not rated':q.score.toFixed(1)+' out of 5'}">${[1,2,3,4,5].map(i=>`<i class="${q.score!==null&&q.score>=i?'filled':''}"></i>`).join('')}</div><span class="score-number">${q.score===null?'Not rated':q.score.toFixed(1)+'/5'}</span><p>${h(clientText(q.note))}</p></div>`).join('')}<details class="score-criteria"><summary>How to read these ratings</summary><p>Recorded 0–100 category scores are displayed on a 0–5 scale by dividing by 20. Missing or ineligible evidence stays unrated. These scores do not predict conversion or replace approval.</p></details></section>`;}
