  function review(p,index,n=0){const item=projectItems(p)[index];if(!item)return stateCard('Creative not found','Return to the project to choose a deliverable.',`<a class="button secondary" href="#project/${h(p.id)}">Back to project</a>`);state.outputIndex=index;state.optionIndex=Math.max(0,Math.min(n,item.results.length-1));const r=item.results[state.optionIndex],key=p.id+':'+item.id,group=assetGroup(p,index);if(p.local&&M.staticRecipe(item.output?.featureId))return staticPlanView(p,index);if(p.local||!r)return breadcrumbs([[p.name,'#project/'+p.id],[item.name]])+heading('Your layout preview','The chosen format is ready for creation.')+journeySteps('review',p)+stateCard('Artwork has not been created',p.local?'Your brief is saved. Generation is not connected to this new interface yet.':'No saved image is available for this deliverable.',(p.local?button('Edit brief','edit-brief','secondary','edit'):'')+`<a class="button primary" href="#project/${h(p.id)}">Back to project</a>`)+`<div class="surface placeholder-art" style="min-height:280px">${icon('image')}<strong>${h(item.name)}</strong><span>${item.output?.width||item.dimensions?.width||'—'} × ${item.output?.height||item.dimensions?.height||'—'}</span></div>`;
    const cache=p.designDetails||reviewCache.get(p.brandId+':'+p.id),unit=cache?.units?.find(u=>u.route===r.route&&u.placementId===r.placementId&&(u.versionId||'original')===(r.versionId||'original'));
    return breadcrumbs([['Projects','#projects'],[p.name,'#project/'+p.id],[item.name]])+heading(group?group.name:'Your creative',item.name)+`<div class="focus-review artwork-only"><section class="artwork-column"><div class="artwork-toolbar artwork-toolbar-right">${state.demo?'':group?collectionBookmark(p,group,r.route):orgButtons(M.creativeKey(p,r))}<div class="review-image-actions" role="group" aria-label="Image actions">${r.originalArtwork?'':`<button type="button" class="review-icon-action" data-action="edit-image" data-index="${state.optionIndex}" aria-label="Edit image" title="Edit image" ${r.imageUrl?'':'disabled'}>${icon('edit')}</button>`}<button type="button" class="review-icon-action" data-action="download" data-index="${state.optionIndex}" aria-label="Download image" title="Download image" ${r.imageUrl?'':'disabled'}>${icon('download')}</button></div></div><div class="focused-art art-frame">${r.imageUrl?`<img src="${h(latestPreview(r))}" alt="${h(item.name+' · '+optionLabel(r.route))}">`:'<div class="placeholder-art">Image unavailable</div>'}</div>${creativeFeedback(p,r)}<p id="downloadStatus" class="hint review-download-status" role="status"></p><div id="downloadRecovery" hidden></div>${r.verificationRetryAvailable&&!r.latestEdit&&(!r.versionId||r.versionId==='original')?`<section class="surface image-recovery"><p>Image ${index+1} was saved, but its checks were interrupted. Other images will stay as they are.</p>${button("Resume checks for image "+(index+1),"retry-image-checks","secondary")}</section>`:""}${collectionStrip(p,index,r)}${item.results.length>1?`<div class="option-strip" aria-label="Alternative sets">${item.results.map((o,i)=>orgMeta(M.creativeKey(p,o)).trashedAt?'':`<article class="option-card ${state.selected[key]===i?'selected':''}"><button class="option-thumbnail ${i===state.optionIndex?'active':''}" data-action="focus-option" data-index="${i}" aria-pressed="${i===state.optionIndex}">${thumb(latestPreview(o),optionLabel(o.route))}<strong>${h(orgMeta(M.creativeKey(p,o)).name||optionLabel(o.route))}</strong><small>${o.latestEdit?'Saved edit':o.ready?'Ready':'Saved image'}</small></button></article>`).join('')}</div>${button(state.selected[key]===state.optionIndex?'Selected':'Use this alternative','select-option','text-button','check',`data-index="${state.optionIndex}" ${group&&collectionRows(p,group,r.route).some(page=>!page.result)?'disabled':''}`)}`:''}</section></div>`;}
  async function hydrateReview(p){if(p.local||state.demo||p.designDetails||p.designDetailsError)return;const key=p.brandId+':'+p.id;if(reviewCache.has(key)||reviewLoading.has(key))return;reviewLoading.add(key);const epoch=state.viewEpoch;try{const data=await D.details(p.sourceJobId||p.id,p.brandId);p.designDetails=data;delete p.designDetailsError;reviewCache.set(key,data);if(state.hash.split('/')[0]!=='review'||state.brand.id!==p.brandId||state.project?.id!==p.id||!$('#rationalePanel'))return;const item=projectItems(p)[state.outputIndex],r=item.results[state.optionIndex],unit=data.units?.find(u=>u.route===r.route&&u.placementId===r.placementId&&(u.versionId||'original')===(r.versionId||'original'));const note=$('#feedbackText')?.value;$('#rationalePanel').innerHTML=rationalePanel(p,item,r,unit);const badge=$('[data-review-status]');if(badge){badge.textContent=reviewedLabel(r,unit);badge.className='status '+(badge.textContent==='Saved review passed'?'green':'amber');}if(note!==undefined)$('#feedbackText').value=note;}catch(e){reviewCache.set(key,{error:e.message});if(epoch===state.viewEpoch&&$('#rationalePanel')){$('#rationalePanel').insertAdjacentHTML('afterbegin',stateCard('Reasoning could not load','Your artwork remains available.',button('Retry reasoning','retry-rationale','text-button'),'error'));}}finally{reviewLoading.delete(key);}}
  function journeysView(){const groups=[...new Set(M.journeys.map(j=>j.group))];return heading('Image studio journeys','Static/image studio: screens, decisions and recovery states.',`<a class="button secondary" href="#static-journeys">Static feature journeys</a>`+button('Start walkthrough','demo-start','primary','arrow'))+stateCard('A safe place to test the interface','Examples are labelled as previews. They do not create jobs, alter saved projects or incur usage.','','info')+`<div class="journey-map">${['Brief','Confirm','Create','Review','Edit','Download'].map((v,i)=>`<span><b>${i+1}</b>${v}</span>`).join('')}</div><div class="journey-catalogue">${groups.map(group=>`<section class="surface"><h2>${h(group)}</h2><div class="scenario-list">${M.journeys.filter(j=>j.group===group).map(j=>`<a class="scenario-link" href="#walkthrough/${j.id}"><span class="scenario-state ${j.state}">${icon(j.state==='error'?'info':j.state==='waiting'?'clock':'window')}</span><span><strong>${h(j.title)}</strong><small>${h(j.story)}</small></span>${icon('arrow')}</a>`).join('')}</div></section>`).join('')}</div>`;}
